    [5212] = { title = "The Flesh Does Not Lie", level = 60, minLevel = 55, objective = "Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", start = { "npc", 11035, "Betina Bigglezink", 1423, 71.7, 49.9 }, finish = { "npc", 11035, "Betina Bigglezink", 1423, 71.7, 49.9 }, next = { 5213 } },
